/**
 * seed-prod.ts — Seed de producción para CEFIDE.
 *
 * Idempotente: usa upsert/createMany skipDuplicates. Seguro de correr
 * múltiples veces en un mismo base de datos.
 *
 * Qué seed:
 *   - ConfigSistema con valores reales
 *   - Actividades reales del gimnasio
 *   - Profesor Juan Pérez (data real del dump)
 *   - Todos los alumnos reales importados (≈300)
 *   - Inscripciones de alumnos (estado inicial: sin clases asignadas,
 *     el admin las configura vía el panel tras el deploy)
 *
 * Qué NO seed:
 *   - Usuario ADMIN: lo crea AdminSeedService en cada boot via ADMIN_EMAIL/ADMIN_PASSWORD
 *   - Passwords de profesores: requieren definición explícita antes del deploy
 *   - Ingresos/Pagos históricos: restaurar desde dump si se necesitan
 *
 * Uso:
 *   pnpm --filter backend exec ts-node --project tsconfig.json -e "
 *     require('ts-node/register'); require('./prisma/seed-prod.ts');
 *   "
 *   — o configurar en package.json: "prisma": { "seed": "ts-node prisma/seed-prod.ts" }
 */

